import sys
import json
import os

def format_date(d):
    if not d:
        return None
    d = str(d).strip()
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    reports_path = os.path.join(packet_dir, 'fda_enforcement_reports.json')
    records_by_entity = {}

    if os.path.exists(reports_path):
        with open(reports_path, 'r') as f:
            reports_data = json.load(f)

        for record in reports_data.get('results', []):
            entity = record.get('recall_number')
            if entity:
                if entity not in records_by_entity:
                    records_by_entity[entity] = []
                records_by_entity[entity].append(record)

    fact_to_field = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date"
    }

    output = {}

    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::', 1)
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        records = records_by_entity.get(entity, [])

        for fact in facts:
            field = fact_to_field.get(fact)
            if not field:
                pair_result[fact] = "ABSENT"
                continue

            values = set()
            for record in records:
                val = record.get(field)
                if val:
                    formatted_val = format_date(val)
                    if formatted_val:
                        values.add(formatted_val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], "fda_enforcement_reports"]
            else:
                pair_result[fact] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

