import sys
import json
import os

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_path = os.path.join(packet_dir, 'fda_enforcement_reports.json')
    if os.path.exists(fda_path):
        with open(fda_path, 'r') as f:
            fda_data = json.load(f)
    else:
        fda_data = {"results": []}

    records_by_entity = {}
    for record in fda_data.get('results', []):
        entity = record.get('recall_number')
        if not entity:
            continue
        if entity not in records_by_entity:
            records_by_entity[entity] = []
        records_by_entity[entity].append(record)

    fact_to_field = {
        "fda.classified_30d": {
            "initiation date": "recall_initiation_date",
            "classification date": "center_classification_date"
        },
        "fda.terminated_180d": {
            "initiation date": "recall_initiation_date",
            "termination date": "termination_date"
        }
    }

    def format_date(d):
        if not isinstance(d, str):
            return None
        d = d.strip()
        if not d:
            return None
        if len(d) == 8 and d.isdigit():
            return f"{d[:4]}-{d[4:6]}-{d[6:]}"
        return d

    results = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::')
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            field = fact_to_field.get(rule_id, {}).get(fact)
            if not field:
                pair_result[fact] = "ABSENT"
                continue

            entity_records = records_by_entity.get(entity, [])

            values = set()
            for record in entity_records:
                val = record.get(field)
                formatted_val = format_date(val)
                if formatted_val:
                    values.add(formatted_val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], "fda_enforcement_reports"]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == '__main__':
    main()

