import sys
import json
import os

def format_date(d):
    if not d:
        return "ABSENT"
    d = str(d).strip()
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_file = os.path.join(packet_dir, 'fda_enforcement_reports.json')

    records = {}
    if os.path.exists(fda_file):
        with open(fda_file, 'r') as f:
            data = json.load(f)
            for result in data.get('results', []):
                recall_number = result.get('recall_number')
                if not recall_number:
                    continue

                init_date = result.get('recall_initiation_date', '')
                class_date = result.get('center_classification_date', '')
                term_date = result.get('termination_date', '')

                init_date_fmt = format_date(init_date)
                class_date_fmt = format_date(class_date)
                term_date_fmt = format_date(term_date)

                if recall_number not in records:
                    records[recall_number] = {
                        'initiation date': set(),
                        'classification date': set(),
                        'termination date': set()
                    }

                if init_date_fmt != "ABSENT":
                    records[recall_number]['initiation date'].add((init_date_fmt, 'fda_enforcement_reports'))
                if class_date_fmt != "ABSENT":
                    records[recall_number]['classification date'].add((class_date_fmt, 'fda_enforcement_reports'))
                if term_date_fmt != "ABSENT":
                    records[recall_number]['termination date'].add((term_date_fmt, 'fda_enforcement_reports'))

    output = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::')
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_output = {}
        for fact in facts:
            if entity not in records:
                pair_output[fact] = "ABSENT"
            else:
                fact_values = records[entity].get(fact, set())
                if len(fact_values) == 0:
                    pair_output[fact] = "ABSENT"
                elif len(fact_values) == 1:
                    pair_output[fact] = list(list(fact_values)[0])
                else:
                    pair_output[fact] = "CONFLICT"
        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

