import json
import os

def format_date(d):
    if not d:
        return "ABSENT"
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d

def main():
    if len(sys.argv) < 3:
        return
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    fda_path = os.path.join(packet_dir, 'fda_enforcement_reports.json')

    records = {}
    if os.path.exists(fda_path):
        with open(fda_path, 'r') as f:
            data = json.load(f)
            for item in data.get('results', []):
                recall_number = item.get('recall_number')
                if not recall_number:
                    continue

                init_date = format_date(item.get('recall_initiation_date'))
                class_date = format_date(item.get('center_classification_date'))
                term_date = format_date(item.get('termination_date'))

                if recall_number not in records:
                    records[recall_number] = {
                        'initiation date': set(),
                        'classification date': set(),
                        'termination date': set()
                    }

                if init_date != "ABSENT":
                    records[recall_number]['initiation date'].add((init_date, 'fda_enforcement_reports'))
                if class_date != "ABSENT":
                    records[recall_number]['classification date'].add((class_date, 'fda_enforcement_reports'))
                if term_date != "ABSENT":
                    records[recall_number]['termination date'].add((term_date, 'fda_enforcement_reports'))

    output = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::')
        facts = manifest.get('facts', {}).get(rule_id, [])

        output[pair] = {}
        for fact in facts:
            if entity not in records:
                output[pair][fact] = "ABSENT"
            else:
                fact_values = records[entity].get(fact, set())
                if len(fact_values) == 0:
                    output[pair][fact] = "ABSENT"
                elif len(fact_values) == 1:
                    output[pair][fact] = list(list(fact_values)[0])
                else:
                    vals = set(v[0] for v in fact_values)
                    if len(vals) > 1:
                        output[pair][fact] = "CONFLICT"
                    else:
                        output[pair][fact] = list(list(fact_values)[0])

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

