import sys
import json
import os

def format_date(d):
    if not d:
        return "ABSENT"
    if len(d) == 8 and d.isdigit():
        return f"{d[:4]}-{d[4:6]}-{d[6:]}"
    return d

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    reports_path = os.path.join(packet_dir, 'fda_enforcement_reports.json')

    data = {}
    if os.path.exists(reports_path):
        with open(reports_path, 'r') as f:
            reports = json.load(f)
            for result in reports.get('results', []):
                recall_number = result.get('recall_number')
                if not recall_number:
                    continue

                init_date = result.get('recall_initiation_date', '')
                class_date = result.get('center_classification_date', '')
                term_date = result.get('termination_date', '')

                if recall_number not in data:
                    data[recall_number] = {
                        'initiation date': set(),
                        'classification date': set(),
                        'termination date': set()
                    }

                data[recall_number]['initiation date'].add(init_date)
                data[recall_number]['classification date'].add(class_date)
                data[recall_number]['termination date'].add(term_date)

    def get_value(entity, field):
        if entity not in data:
            return "ABSENT"
        values = data[entity][field]
        if len(values) == 0:
            return "ABSENT"
        if len(values) > 1:
            return "CONFLICT"
        val = list(values)[0]
        if not val:
            return "ABSENT"
        return [format_date(val), "fda_enforcement_reports"]

    output = {}
    for pair in manifest.get('pairs', []):
        rule_id, entity = pair.split('::')
        facts = manifest.get('facts', {}).get(rule_id, [])

        pair_output = {}
        for fact in facts:
            if fact == 'initiation date':
                pair_output[fact] = get_value(entity, 'initiation date')
            elif fact == 'classification date':
                pair_output[fact] = get_value(entity, 'classification date')
            elif fact == 'termination date':
                pair_output[fact] = get_value(entity, 'termination date')

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

